import{_ as e,o,c as l,a5 as t}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 70 话 兼容矩阵与渐进增强兜底","description":"","frontmatter":{},"headers":[],"relativePath":"comics/quality/EP.70-compat-fallback.md","filePath":"comics/quality/EP.70-compat-fallback.md","lastUpdated":1793853676000}'),c={name:"comics/quality/EP.70-compat-fallback.md"};function r(d,a,i,s,h,p){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-70-话-兼容矩阵与渐进增强兜底" tabindex="-1">漫画 · 第 70 话 兼容矩阵与渐进增强兜底 <a class="header-anchor" href="#漫画-·-第-70-话-兼容矩阵与渐进增强兜底" aria-label="Permalink to &quot;漫画 · 第 70 话 兼容矩阵与渐进增强兜底&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/quality/04-compat-fallback">docs/quality/04-compat-fallback.md</a> ｜ 原画：<a href="./EP.70-compat-fallback.svg">EP.70-compat-fallback.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。她用 <code>:has()</code> 做了「有图两列」卡片，觉得代码又短又优雅。</li><li><strong>标签君</strong>：结构师。灰度到旧版 Safari 后，他接到一整页布局错乱的告警。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>增强样式直接写在基础规则里，旧引擎不支持 <code>:has()</code> 时整段规则失效，卡片全部退回错位布局。标签君把基础层改成单列，把 <code>:has()</code> 分支放进 <code>@supports</code>，并给 popover 菜单补了 <code>hidden</code> + 显隐类的兜底。两人还建立了兼容矩阵，标注每个特性的状态、使用位置、兜底方案与负责人。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>问题不在 <code>:has()</code> 本身，而在它的位置。增强能力一旦写进基础路径，旧环境不是「体验差一点」，而是「布局直接坏掉」。没有兼容矩阵时，评审也没人确认这个特性到底能不能直接用。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>渐进增强要求能力分层：基础层用语义 HTML 与普通 CSS 保证任务可完成；增强层用 <code>@supports</code> 或 <code>in</code> 检测叠加现代能力；兜底层提供等价路径。检测能力而不是 UA——UA 会伪装、会过期，<code>CSS.supports(&#39;selector(:has(*))&#39;)</code> 才可靠。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>标签君把基础布局改为单列，<code>:has()</code> 两列放进 <code>@supports</code>；菜单在支持 popover 时顶层渲染，不支持时用 <code>hidden</code> 与 <code>aria-expanded</code> 管理；每个增强组件都加一条「强制降级」用例。示例里的「模拟不支持」开关就是这条用例的现场版：关掉增强后，功能仍然完整。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>主任务必须在无 JS / 旧引擎下可完成，再谈增强。</li><li>检测能力不检测 UA，<code>@supports</code> 与 <code>in</code> 更可靠。</li><li>增强样式必须放进 <code>@supports</code>，不能混进基础规则。</li><li>兜底要可测试，提供强制降级开关或用例。</li><li>兼容矩阵要标注状态、位置、兜底与负责人。</li><li>不要为长尾过度兜底，按用户占比与任务重要性取舍。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>@supports</code> 里只放增强样式，基础样式要写在检测之外？</p><p><strong>答</strong>：<code>@supports</code> 的作用是「条件满足才应用」。如果把基础布局也放进去，不支持时整段规则都不生效，页面就没有布局了。正确写法是基础规则在外、增强规则在 <code>@supports</code> 内，这样不支持的环境拿到的是朴素但完整的布局，支持的环境再升级。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>点击「模拟不支持环境」，观察卡片回到单列、菜单改走显隐路径：<a href="./../../examples/quality/04-compat-fallback">examples/quality/04-compat-fallback</a></li><li>查看能力检测面板，确认 <code>:has()</code> / popover / 锚点定位 / dialog 的真实支持状态。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>质量门禁篇收官。第 71 话起进入实战巩固篇：《CSS/HTML 反例库》——三十个典型错误写法与修复。</p>',22)])])}const m=e(c,[["render",r]]);export{u as __pageData,m as default};
